import{_ as n,l as s,o as e,c as o,v as t,p as d,x as r,d as l,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"股指期货基差与对冲成本","description":"","frontmatter":{"title":"股指期货基差与对冲成本","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-index-basis-hedge-cost.md","filePath":"quant/cn-index-basis-hedge-cost.md","lastUpdated":1789023840000}'),m={name:"quant/cn-index-basis-hedge-cost.md"};function p(_,a,E,u,B,A){const i=s("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="股指期货基差与对冲成本" tabindex="-1">股指期货基差与对冲成本 <a class="header-anchor" href="#股指期货基差与对冲成本" aria-label="Permalink to &quot;股指期货基差与对冲成本&quot;">​</a></h1><div class="epigraph"><p>贴水年化不是中性策略的确定收益。它是对冲拥挤、分红、保证金与展期的市场价格；变深时空头赢、多头相对期货输。</p><footer>—— 中国金融期货交易所股指期货合约及结算细则；持有成本与基差见指数套利教科书处理；对照[保证金与贴水](/quant/cn-index-fut-basis)</footer></div><p><a href="/quant/cn-securities-lending">上一课</a>关闭或收紧了个股空头。<a href="/quant/cn-index-fut-basis">股指期货保证金与贴水</a>已写合约乘数、结算价、分红季节与 IC/IM 深度贴水。本课的缺口是<strong>把它接到产品账单</strong>：指增、私募中性、期现套利的对冲成本如何从基差、展期、保证金与冲击加总。不重导 \\(F=Se^{(r-q)\\tau}\\) 的全文，只补产品层会计。后课 ETF 期权提供另一套波动率工具。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>中性产品空期货、多选股组合，净值 ≈ 选股超额 + 基差变动 − 保证金与冲击。把期初贴水年化加进预期超额，等于假设贴水单调收敛且保证金免费。现实：贴水可继续变深（对冲拥挤、融券更难）、展期把近月换成远月、VM 抽现金。问题是定义可实现对冲成本</p> \\[c_{\\mathrm{hedge}}=\\underbrace{\\Delta \\mathrm{basis}}_{\\text{盯市}}+\\underbrace{c_{\\mathrm{roll}}}_{\\text{展期}}+\\underbrace{c_{\\mathrm{margin}}}_{\\text{占用}}+\\underbrace{c_{\\mathrm{impact}}}_{\\text{期货与篮子冲击}}. \\]<p>选股超额必须在扣 \\(c_{\\mathrm{hedge}}\\) 后报告。公募若只用期货替代股票仓位，成本进入跟踪误差与费用，同样不能当 alpha。</p><p>IF/IH 与 IC/IM 的 \\(c_{\\mathrm{hedge}}\\) 结构不同：前者更接近分红与利率，后者更接近拥挤。用错合约对冲 500/1000 增强，市值残差会进「选股」。</p><h3 id="展期日历是强制交易" tabindex="-1">展期日历是强制交易 <a class="header-anchor" href="#展期日历是强制交易" aria-label="Permalink to &quot;展期日历是强制交易&quot;">​</a></h3><p>近月到期必须展期。展期成交的是月差，不是指数。远月更贴则空头展期付费。流动性在远月更差，冲击占 \\(c_{\\mathrm{impact}}\\) 的大头。回测用收盘点位展期、零滑点，会系统性低估中性成本。平今手续费历史上曾很高，须按当时费率。</p><p><span class="marginnote">现货涨跌停、期货 ±10% 停板，基差可以超出无套利带且无法对锁。该日 \\(c_{\\mathrm{hedge}}\\) 的方差来自制度，应单列。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每日记账：期货结算盈亏、相对现货篮子（或 ETF）的基差、保证金占用的融资成本、展期日单独腿。篮子用可复制组合，不是指数点，见期现课。压力：贴水扩大到历史分位、保证金上调、限仓。容量：中金所持仓限额与市场深度给出空头供给上限；超过则 \\(c_{\\mathrm{hedge}}\\) 陡增，产品应降杠杆而非提高名义。</p><p>与<a href="/quant/live-capacity-estimate">实盘容量</a> 对齐：中性产品的 \\(A^\\ast\\) 常由期货腿决定。与指增对齐：未对冲的增强没有 \\(c_{\\mathrm{hedge}}\\) 的期货项，但有基准调仓冲击。</p><h3 id="分红窗口" tabindex="-1">分红窗口 <a class="header-anchor" href="#分红窗口" aria-label="Permalink to &quot;分红窗口&quot;">​</a></h3><p>二季度 IF/IH 贴水含分红折现。用事后实现 \\(q\\) 会前视。对冲成本分解应把「预期分红」与「拥挤残差」分开，避免把日历效应当选股技能。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>空头工具越少，期货越贵（贴水越深）。转融券收紧 → 中性需求 → 贴水，是同一供给曲线。做多贴水（买期货、卖现货）受现货借券与卖空约束，收敛可以很慢。因此贴水可以长期存在，不是免费午餐。CCP 每日 VM 把基差变动变成现金，路径依赖强于「持有到期的年化」。</p>',18)),(e(),d(c,null,{default:r(()=>[h(i,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20Crowd%5B%22%E4%B8%AD%E6%80%A7%E4%B8%8E%E5%A5%97%E4%BF%9D%E5%8D%96%E5%8E%8B%22%5D%20--%3E%20Basis%5B%22%E8%B4%B4%E6%B0%B4%22%5D%0A%20%20Div%5B%22%E9%A2%84%E6%9C%9F%E5%88%86%E7%BA%A2%22%5D%20--%3E%20Basis%0A%20%20Basis%20--%3E%20PnL%5B%22%E6%9C%9F%E8%B4%A7%E7%9B%AF%E5%B8%82%22%5D%0A%20%20Roll%5B%22%E5%B1%95%E6%9C%9F%E6%9C%88%E5%B7%AE%22%5D%20--%3E%20Cost%5B%22%E5%AF%B9%E5%86%B2%E6%88%90%E6%9C%AC%22%5D%0A%20%20Mgn%5B%22%E4%BF%9D%E8%AF%81%E9%87%91%E5%8D%A0%E7%94%A8%22%5D%20--%3E%20Cost%0A%20%20PnL%20--%3E%20Cost%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供逼仓、操纵交割结算价或利用未公开套保额度的方法。交割结算价为指数最后两小时均价，对冲应对该定义。境外指数期货对 A 股的映射有监管与基差，不能当同一工具。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>对冲成本 = 基差盯市 + 展期 + 保证金 + 冲击；贴水年化不是确定 alpha。</li><li>IC/IM 与 IF/IH 结构不同；用错合约留下市值暴露。</li><li>融券管道影响期货拥挤，两课必须联立。</li><li>出处：中金所股指期货细则；本栏 <code>cn-index-fut-basis</code>；持有成本理论。</li></ul>',4))])}const q=n(m,[["render",p]]);export{f as __pageData,q as default};
